#!/bin/sh

# Check that the generated documentation files committed under doc are the
# same as the ones generated by doc/build.sh from the current code.
#
# The swagger must be built first, e.g.:
#
# sh stackgres-k8s/ci/build/build.sh restapi-java
# sh stackgres-k8s/ci/build/build-functions.sh extract restapi-java stackgres-k8s/src/restapi/target/swagger-merged.yaml

set -e

cd "$(dirname "$0")/.."

SWAGGER_FILE="stackgres-k8s/src/restapi/target/swagger-merged.yaml"
DOC_SWAGGER_FILE="doc/themes/sg-doc/static/sg-swagger.yaml"

if [ ! -f "$SWAGGER_FILE" ]
then
  >&2 echo "$SWAGGER_FILE not found, please build the restapi-java module first"
  exit 1
fi

if ! cmp -s "$SWAGGER_FILE" "$DOC_SWAGGER_FILE"
then
  >&2 echo "$DOC_SWAGGER_FILE differs from the built $SWAGGER_FILE:"
  >&2 echo
  diff -u "$DOC_SWAGGER_FILE" "$SWAGGER_FILE" | head -n 100 >&2 || true
  >&2 echo
  >&2 echo "Please run \`sh doc/build.sh\` after building the restapi-java module and commit the changes"
  exit 1
fi

sh doc/build.sh

if [ -n "$(git status --porcelain -- doc)" ]
then
  >&2 echo "The generated documentation files under doc are not up to date:"
  >&2 echo
  git status --porcelain -- doc >&2
  git diff -- doc | head -n 200 >&2
  >&2 echo
  >&2 echo "Please run \`sh doc/build.sh\` and commit the changes"
  exit 1
fi

echo "The generated documentation files under doc are up to date"
